SINA_SMART["hemato1-bleeding"] = {"lecture":"hemato1-bleeding","title":"Approach to the bleeding patient","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-bleeding:e0","text":"Bleeding disorders: 2nd most common haematology consultation.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e1","text":"History is the best predictor; examination + history ~90% accurate.","topic":"History and examination","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e2","text":"Mucocutaneous bleeding → primary haemostasis; joints/muscles → coagulation factor.","topic":"History and examination","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e3","text":"Lifelong bleeding (umbilical stump, circumcision) → inherited.","topic":"History and examination","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e4","text":"Aspirin and NSAIDs impair primary haemostasis.","topic":"History and examination","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e5","text":"ISTH-BAT standardises bleeding scores; four W's: who, when, where, what.","topic":"History and examination","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e6","text":"1st line: CBC, PFA-100/bleeding time, PT, aPTT, fibrinogen.","topic":"Laboratory testing and treatment","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e7","text":"2nd line: VWF, aggregometry, FVIII/FIX, mixing studies; 3rd: inhibitors, α2-antiplasmin, PAI-1.","topic":"Laboratory testing and treatment","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e8","text":"Tranexamic acid blocks plasminogen → plasmin.","topic":"Laboratory testing and treatment","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-bleeding:e9","text":"VWD: ~1/1,000; type 1 most common, type 3 most severe; tranexamic acid, desmopressin, concentrates.","topic":"Clinical application: von Willebrand disease","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"u12hcy":"a","1f9kst0":"a","226s15":"a","18mfjrf":"a","r2pi98":"a","t0oofz":"a","4kjpun":"a","1ghbevh":"a","1u6j2a4":"a","ltdjhg":"a","1frgj5n":"a","18hzmmn":"a","tyxndh":"x"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-bleeding:e0":{"s":0,"u":["Bleeding disorders: 2nd most common haematology consultation.","Bleeding disorders are the second most common reason for haematology consultation after anaemia and are often underdiagnosed, because bleeding histories are subjective and symptoms may be taken as normal."],"dp":[{"h":"Why heavy periods can reveal a bleeding disorder","t":"Menstruation is a recurring haemostatic challenge, so women with mild von Willebrand disease or platelet disorders often first present with heavy periods and iron deficiency anaemia rather than dramatic bleeding. Asking about menorrhagia, and screening women with it for a bleeding disorder, uncovers many cases that would otherwise be missed until surgery or childbirth. Source: the lecture's personal and family history slides."}]},"hemato1-bleeding:e1":{"s":1,"u":["History is the best predictor; examination + history ~90% accurate.","A detailed history is the best predictor of a bleeding disorder.","Family history , including consanguinity."],"dp":[]},"hemato1-bleeding:e2":{"s":1,"u":["Mucocutaneous bleeding → primary haemostasis; joints/muscles → coagulation factor.","Type and site : skin and mucosa (petechiae, purpura, bruises, epistaxis, gum bleeding, menorrhagia, haematuria) suggest a primary haemostasis defect; deep tissue, joint and muscle bleeding suggests a coagulation factor defect.","Drugs : aspirin and NSAIDs impair primary haemostasis and should be avoided before surgery or testing."],"dp":[]},"hemato1-bleeding:e3":{"s":1,"u":["Lifelong bleeding (umbilical stump, circumcision) → inherited.","Duration : lifelong (childhood epistaxis, umbilical stump bleeding, bleeding after circumcision) suggests an inherited disorder.","Patients may under- or overstate bleeding; inherited disorders are common in women with menorrhagia."],"dp":[]},"hemato1-bleeding:e4":{"s":1,"u":["Aspirin and NSAIDs impair primary haemostasis.","Drugs : aspirin and NSAIDs impair primary haemostasis and should be avoided before surgery or testing."],"dp":[]},"hemato1-bleeding:e5":{"s":1,"u":["ISTH-BAT standardises bleeding scores; four W's: who, when, where, what.","Bleeding scores such as the ISTH Bleeding Assessment Tool (BAT) (and a paediatric version) standardise the evaluation."],"dp":[]},"hemato1-bleeding:e6":{"s":2,"u":["1st line: CBC, PFA-100/bleeding time, PT, aPTT, fibrinogen.","First line : CBC, bleeding time or PFA-100 , PT , aPTT , fibrinogen ."],"dp":[]},"hemato1-bleeding:e7":{"s":2,"u":["2nd line: VWF, aggregometry, FVIII/FIX, mixing studies; 3rd: inhibitors, α2-antiplasmin, PAI-1.","Third line : inhibitors, α2-antiplasmin, PAI-1.","Second line : VWF antigen and activity , platelet aggregometry, factors VIII and IX then others, mixing studies ."],"dp":[]},"hemato1-bleeding:e8":{"s":2,"u":["Tranexamic acid blocks plasminogen → plasmin.","Treatment : general measures (hepatitis A and B vaccination, gynaecological evaluation for menorrhagia, avoid aspirin and NSAIDs); local measures (direct pressure; stepwise plan for nosebleeds up to cautery); indirect therapies: tranexamic acid (antifibrinolytic: blocks plasminogen → plasmin; useful in haemophilia A, VWD and anticoagulant bleeding) and hormonal treatment of menorrhagia (pill, levonorgestrel IUD, endometrial ablation); replacement therapy for the specific deficiency following guidelines."],"dp":[]},"hemato1-bleeding:e9":{"s":3,"u":["VWD: ~1/1,000; type 1 most common, type 3 most severe; tranexamic acid, desmopressin, concentrates.","Type 1 : reduced VWF, the most common; type 2 : dysfunctional VWF (four subtypes); type 3 : absent VWF, rare and most severe.","Management: education (bleeding risk, surgery and pregnancy planning, avoid antiplatelet drugs), tranexamic acid , desmopressin , VWF or FVIII-VWF concentrates, and prophylaxis for recurrent bleeding."],"dp":[]}},"meta":{"u12hcy":{"a":"relationship","vg":"hemato1-bleeding:e0/relationship/1"},"1f9kst0":{"a":"recall","vg":"hemato1-bleeding:e1/recall/1"},"226s15":{"a":"recall","vg":"hemato1-bleeding:e2/recall/1"},"18mfjrf":{"a":"recall","vg":"hemato1-bleeding:e2/recall/1"},"r2pi98":{"a":"recall","vg":"hemato1-bleeding:e3/recall/1"},"t0oofz":{"a":"recall","vg":"hemato1-bleeding:e5/recall/1"},"4kjpun":{"a":"recall","vg":"hemato1-bleeding:e1/recall/2"},"1ghbevh":{"a":"recall","vg":"hemato1-bleeding:e6/recall/1"},"1u6j2a4":{"a":"recall","vg":"hemato1-bleeding:e8/recall/1"},"ltdjhg":{"a":"recall","vg":"hemato1-bleeding:e9/recall/1"},"1frgj5n":{"a":"recall","vg":"hemato1-bleeding:e9/recall/1"},"18hzmmn":{"a":"recall","vg":"hemato1-bleeding:e4/recall/1"}},"explRev":"079d79a3607b"};
